<div class="panel" style="max-width:850px;margin:20px auto"><div style="display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap;align-items:center"><div><span class="eyebrow">ORDER DETAIL</span><h2 style="margin:8px 0">#<?= e($order['order_code']) ?></h2><p class="hint">Ngày tạo: <?= date('d/m/Y H:i',strtotime($order['created_at'])) ?></p></div><span class="status <?= e($order['status']) ?>"><?= e(format_order_status($order['status'])) ?></span></div>
<div class="spec-grid" style="margin-top:15px"><div><h3>Thông tin nhận hàng</h3><p class="hint">Họ tên: <?= e($order['customer_name']) ?></p><p class="hint">Điện thoại: <?= e($order['customer_phone']) ?></p><p class="hint">Địa chỉ: <?= e($order['address']) ?></p><?php if($order['note']):?><p class="hint">Ghi chú: <?= e($order['note']) ?></p><?php endif;?></div><div><h3>Thanh toán</h3><p class="hint">Hình thức: <?= $order['payment_method']==='cod'?'Thanh toán khi nhận hàng':'Chuyển khoản (demo)' ?></p><p class="hint">Trạng thái: <?= $order['payment_status']==='paid'?'Đã thanh toán':'Chưa thanh toán' ?></p></div></div>
