<div style="max-width:310px;margin:20px 0 0 auto"><div class="summary-row"><span>Tạm tính</span><strong><?= money($order['subtotal']) ?></strong></div><div class="summary-row"><span>Vận chuyển</span><strong><?= money($order['shipping_fee']) ?></strong></div><div class="summary-row total"><span>Tổng cộng</span><strong><?= money($order['total']) ?></strong></div></div></div>
